Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "fold": [
        "ENE · período",
        "CNF · período",
        "REL · período",
        "PAR · período",
        "Sem razão · período",
        "Origem local · período",
        "Origem sistêmica · período",
        "Sem origem · período"
      ],
      "as": [
        "medida",
        "gwh"
      ]
    },
    {
      "calculate": "replace(datum.medida, '' · período'', '''')",
      "as": "cat"
    },
    {
      "calculate": "indexof([''Origem local'',''Origem sistêmica'',''Sem origem''], datum.cat) >= 0 ? ''Origem'' : ''Razão''",
      "as": "grupo"
    },
    {
      "calculate": "indexof([''ENE'',''CNF'',''REL'',''PAR'',''Sem razão'',''Origem local'',''Origem sistêmica'',''Sem origem''], datum.cat)",
      "as": "ordem"
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "gwh",
          "as": "tot"
        }
      ],
      "groupby": [
        "grupo"
      ]
    },
    {
      "calculate": "datum.tot > 0 ? datum.gwh / datum.tot : 0",
      "as": "pct"
    },
    {
      "window": [
        {
          "op": "sum",
          "field": "pct",
          "as": "fim"
        }
      ],
      "groupby": [
        "grupo"
      ],
      "sort": [
        {
          "field": "ordem"
        }
      ],
      "frame": [
        null,
        0
      ]
    },
    {
      "calculate": "datum.fim - datum.pct",
      "as": "ini"
    },
    {
      "calculate": "datum.fim - datum.pct / 2",
      "as": "meio"
    }
  ],
  "encoding": {
    "y": {
      "field": "grupo",
      "type": "nominal",
      "title": null,
      "sort": [
        "Razão",
        "Origem"
      ],
      "axis": {
        "labelFontSize": 11,
        "labelColor": "#191919",
        "labelFontWeight": "bold",
        "ticks": false
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "height": {
          "band": 0.62
        }
      },
      "encoding": {
        "x": {
          "field": "ini",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "domain": [
              0,
              1
            ]
          }
        },
        "x2": {
          "field": "fim"
        },
        "color": {
          "field": "cat",
          "type": "nominal",
          "scale": {
            "domain": [
              "ENE",
              "CNF",
              "REL",
              "PAR",
              "Sem razão",
              "Origem local",
              "Origem sistêmica",
              "Sem origem"
            ],
            "range": [
              "#252423",
              "#605E5C",
              "#A19F9D",
              "#967100",
              "#E1DFDD",
              "#F2C811",
              "#191919",
              "#E1DFDD"
            ]
          },
          "legend": {
            "orient": "bottom",
            "columns": 4,
            "title": null,
            "labelFontSize": 9,
            "symbolSize": 60,
            "columnPadding": 8,
            "labelLimit": 90,
            "labelExpr": "replace(replace(datum.label, ''Origem local'', ''Local''), ''Origem sistêmica'', ''Sistêmica'')"
          }
        },
        "tooltip": [
          {
            "field": "grupo",
            "title": "Grupo"
          },
          {
            "field": "cat",
            "title": "Categoria"
          },
          {
            "field": "gwh",
            "title": "GWh",
            "format": ",.0f"
          },
          {
            "field": "pct",
            "title": "Participação",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum.pct >= 0.07"
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 10,
        "fontWeight": "bold",
        "align": "center"
      },
      "encoding": {
        "x": {
          "field": "meio",
          "type": "quantitative"
        },
        "text": {
          "field": "pct",
          "format": ".0%"
        },
        "color": {
          "condition": {
            "test": "indexof([''ENE'',''CNF'',''Origem sistêmica'',''PAR''], datum.cat) >= 0",
            "value": "#FFFFFF"
          },
          "value": "#191919"
        }
      }
    }
  ]
}'
